WITH enriched AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, DENSE_RANK() OVER w_ordered AS cost_dense_rank, CUME_DIST() OVER (PARTITION BY order_id ORDER BY cost DESC NULLS FIRST) AS cost_cume_dist, CUME_DIST() OVER (PARTITION BY order_id, status ORDER BY cost DESC) AS cost_cume_dist_2, PERCENT_RANK() OVER (PARTITION BY status, carrier ORDER BY cost DESC NULLS FIRST) AS cost_percent_rank FROM shipments WINDOW w_ordered AS (ORDER BY cost DESC NULLS LAST)) SELECT status, PERCENTILE_APPROX(cost_cume_dist, 0.5) AS cost_cume_dist_p50, COUNT_IF(status = 'DELIVERED') AS delivered_events, AVG(cost_percent_rank) FILTER (WHERE status = 'IN_TRANSIT') AS in_transit_avg_cost_percent_rank, PERCENTILE_APPROX(cost_dense_rank, ARRAY(0.25, 0.5, 0.75)) AS cost_dense_rank_quartiles, COUNT(*) AS event_count, MAX(cost_percent_rank) AS max_cost_percent_rank FROM enriched GROUP BY status ORDER BY delivered_events
